/**
 * Cortex Multimodal Speech Recognition & Voice Activity Subsystem
 *
 * Implements low-latency, full-duplex speech recognition with acoustic efference suppression:
 * 1. Web Speech API engine with continuous streaming and partial token callbacks.
 * 2. Integrated Voice Activity Detection (VAD) and audio level meter.
 * 3. Efference Copy Integration: Discards self-speech reverberations generated by TTS.
 * 4. Punctuation & silence pacing heuristic for natural human-agent turn-taking.
 */

import { isAcousticEcho } from './cortex-efference-copy';

export interface SpeechRecognitionCallbacks {
  onPartial?: (text: string) => void;
  onFinal?: (text: string) => void;
  onError?: (error: string) => void;
  onAudioLevel?: (level: number) => void; // 0.0 - 1.0
  onStateChange?: (active: boolean) => void;
}

export class CortexMultimodalSpeech {
  private static instance: CortexMultimodalSpeech | null = null;
  private recognition: any = null;
  private isListeningActive = false;
  private audioContext: AudioContext | null = null;
  private analyser: AnalyserNode | null = null;
  private mediaStream: MediaStream | null = null;
  private animFrameId: number | null = null;
  private callbacks: SpeechRecognitionCallbacks = {};
  private activeUtterance = '';

  public static getInstance(): CortexMultimodalSpeech {
    if (!CortexMultimodalSpeech.instance) {
      CortexMultimodalSpeech.instance = new CortexMultimodalSpeech();
    }
    return CortexMultimodalSpeech.instance;
  }

  public isAvailable(): boolean {
    if (typeof window === 'undefined') return false;
    const win = window as any;
    return !!(win.SpeechRecognition || win.webkitSpeechRecognition);
  }

  public async startListening(callbacks: SpeechRecognitionCallbacks = {}): Promise<boolean> {
    if (this.isListeningActive) return true;
    this.callbacks = callbacks;

    if (typeof window === 'undefined') return false;
    const win = window as any;
    const SpeechRec = win.SpeechRecognition || win.webkitSpeechRecognition;

    if (!SpeechRec) {
      if (this.callbacks.onError) this.callbacks.onError('Web Speech API not supported in this browser.');
      return false;
    }

    try {
      this.recognition = new SpeechRec();
      this.recognition.continuous = true;
      this.recognition.interimResults = true;
      this.recognition.lang = 'en-US';

      this.recognition.onstart = () => {
        this.isListeningActive = true;
        if (this.callbacks.onStateChange) this.callbacks.onStateChange(true);
      };

      this.recognition.onresult = (event: any) => {
        let interimText = '';
        let finalText = '';

        for (let i = event.resultIndex; i < event.results.length; ++i) {
          const transcript = event.results[i][0].transcript;
          if (event.results[i].isFinal) {
            finalText += transcript;
          } else {
            interimText += transcript;
          }
        }

        const candidate = (finalText || interimText).trim();

        // Efference copy check: Suppress acoustic echo if TTS was speaking this
        if (candidate && isAcousticEcho(candidate)) {
          return;
        }

        if (interimText && this.callbacks.onPartial) {
          this.callbacks.onPartial(interimText.trim());
        }

        if (finalText && this.callbacks.onFinal) {
          this.activeUtterance = finalText.trim();
          this.callbacks.onFinal(this.activeUtterance);
        }
      };

      this.recognition.onerror = (event: any) => {
        if (event.error !== 'no-speech') {
          if (this.callbacks.onError) this.callbacks.onError(event.error || 'Speech recognition error');
        }
      };

      this.recognition.onend = () => {
        // If we want continuous active listening, auto-restart unless manually stopped
        if (this.isListeningActive) {
          try {
            this.recognition.start();
          } catch {}
        } else {
          if (this.callbacks.onStateChange) this.callbacks.onStateChange(false);
        }
      };

      this.recognition.start();
      await this.startAudioMeter();
      return true;
    } catch (err: any) {
      if (this.callbacks.onError) this.callbacks.onError(err.message || 'Failed to start speech recognition');
      return false;
    }
  }

  public stopListening(): void {
    this.isListeningActive = false;
    if (this.recognition) {
      try {
        this.recognition.stop();
      } catch {}
      this.recognition = null;
    }
    this.stopAudioMeter();
    if (this.callbacks.onStateChange) this.callbacks.onStateChange(false);
  }

  private async startAudioMeter(): Promise<void> {
    try {
      if (!navigator.mediaDevices?.getUserMedia) return;
      this.mediaStream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      this.audioContext = new AudioCtx();
      const source = this.audioContext.createMediaStreamSource(this.mediaStream);
      this.analyser = this.audioContext.createAnalyser();
      this.analyser.fftSize = 256;
      source.connect(this.analyser);

      const dataArray = new Uint8Array(this.analyser.frequencyBinCount);
      const updateMeter = () => {
        if (!this.analyser || !this.isListeningActive) return;
        this.analyser.getByteFrequencyData(dataArray);
        let sum = 0;
        for (let i = 0; i < dataArray.length; i++) {
          sum += dataArray[i];
        }
        const avg = sum / dataArray.length;
        const normalized = Math.min(1.0, avg / 128);
        if (this.callbacks.onAudioLevel) {
          this.callbacks.onAudioLevel(normalized);
        }
        this.animFrameId = requestAnimationFrame(updateMeter);
      };
      updateMeter();
    } catch {
      // Audio meter optional
    }
  }

  private stopAudioMeter(): void {
    if (this.animFrameId) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }
    if (this.mediaStream) {
      this.mediaStream.getTracks().forEach((t) => t.stop());
      this.mediaStream = null;
    }
    if (this.audioContext) {
      try { this.audioContext.close(); } catch {}
      this.audioContext = null;
    }
    this.analyser = null;
  }

  public getIsListening(): boolean {
    return this.isListeningActive;
  }
}

export function getCortexMultimodalSpeech(): CortexMultimodalSpeech {
  return CortexMultimodalSpeech.getInstance();
}

